#include <components/nif/controller.hpp>
#include <fstream>
#include <iostream>
#include <iomanip>
int main(int argc,char**argv){
 if(argc!=2)return 2;
 Nif::NIFFile file(VFS::Path::toNormalized(argv[1]));Nif::Reader reader(file,nullptr);reader.parse(std::make_unique<std::ifstream>(argv[1],std::ios::binary));
 std::cout<<"file "<<std::quoted(argv[1])<<" version "<<file.mVersion<<" records "<<file.mRecords.size()<<" skin "<<file.mUseSkinning<<'\n';
 for(const auto* root:file.mRoots){std::cout<<"root "<<root->mRecordIndex<<' '<<root->mRecordName;if(const auto* n=dynamic_cast<const Nif::NiObjectNET*>(root))std::cout<<' '<<std::quoted(n->mName);std::cout<<'\n';}
 for(const auto& record:file.mRecords){
  if(const auto* extra=dynamic_cast<const Nif::NiStringExtraData*>(record.get()))std::cout<<"extra "<<record->mRecordIndex<<' '<<std::quoted(extra->mName)<<' '<<std::quoted(extra->mData)<<'\n';
  if(const auto* n=dynamic_cast<const Nif::NiAVObject*>(record.get())){std::cout<<"node "<<record->mRecordIndex<<' '<<std::quoted(n->mName)<<" scale "<<n->mTransform.mScale<<" translation "<<n->mTransform.mTranslation.x()<<' '<<n->mTransform.mTranslation.y()<<' '<<n->mTransform.mTranslation.z()<<'\n';for(const auto& e:n->getExtraList())if(!e.empty())std::cout<<"extra-link "<<record->mRecordIndex<<' '<<e->mRecordIndex<<'\n';}
  if(const auto* seq=dynamic_cast<const Nif::NiControllerSequence*>(record.get())){std::cout<<"sequence "<<record->mRecordIndex<<' '<<std::quoted(seq->mName)<<" start "<<seq->mStartTime<<" stop "<<seq->mStopTime<<'\n';for(const auto& b:seq->mControlledBlocks)std::cout<<"controlled "<<std::quoted(b.mNodeName)<<" priority "<<unsigned(b.mPriority)<<'\n';}
  if(const auto* keys=dynamic_cast<const Nif::NiTextKeyExtraData*>(record.get()))for(const auto& k:keys->mList)std::cout<<"key "<<k.mTime<<' '<<std::quoted(k.mText)<<'\n';
 }
}

